script:
carrier_event = { #titanic life
	id = colony_mod.2
	title = "colony_mod.2.name"
	desc = "colony_mod.2.desc"
	picture = GFX_evt_alien_nature
	show_sound = event_air_raid_siren
	location = ROOT
	trackable = yes

	pre_triggers = {
		has_owner = yes
		is_homeworld = no
		original_owner = yes
		is_ai = no
		has_ground_combat = no
		is_capital = no
	}

	trigger = {
		has_modifier = "titanic_life"
		NOR = {
			has_carrier_flag = titanic_life_colony_flag
			is_planet_class = pc_volcanic
		}
		pop_amount > 0
	}

	immediate = {
		set_carrier_flag = titanic_life_colony_flag
	}

	is_triggered_only = yes

	option = {
		name = colony_mod.2.a# yes
		# study them, may have bad outcome, such as a hostile unit spawning
		enable_special_project = {
			name = "titanic_life_study_normal"
			location = this
			owner = root
		}
	}

	option = {
		name = colony_mod.2.b# no
		#no effect, don't bother them
	}

	option = {
		name = colony_mod.2.c
		trigger = {
			owner = { is_xenophile = yes #nice, for xenophiles
			}
		}
		# study them, bad outcome less likely but takes longer.
		# Remove blockers in success result
		enable_special_project = {
			name = "titanic_life_study_nice"
			location = this
			owner = root
		}
		hidden_effect = {
			set_carrier_flag = nice_titan_study
		}
	}

	option = {
		name = colony_mod.2.d
		trigger = {
			owner = {
				OR = {
					is_xenophobe = yes
					is_hive_empire = yes
				} #mean, for xenophobe
			}
		}
		# study them, takes less time but you will likely get a bad effect too
		# huge food output increase
		enable_special_project = {
			name = "titanic_life_study_mean"
			location = this
			owner = root
		}
		if = {
			limit = { owner = { NOT = { has_origin = origin_evolutionary_predators } } }
			add_modifier = {
				modifier = "eat_the_titans"
				days = -1
			}
		}
		else = {
			add_modifier = {
				modifier = "eat_the_titans_evopred"
				days = -1
			}
		}
	}

}

