script:
country_event = {
	id = colony.9850
	title = "colony.9850.name"
	desc = {
		trigger = { is_machine_empire = yes }
		text = "colony.9850.desc.robot"
	}
	desc = {
		trigger = { is_hive_empire = yes }
		text = "colony.9850.desc.hive"
	}
	desc = {
		trigger = { is_regular_empire = yes }
		text = "colony.9850.desc"
	}
	picture = GFX_evt_atmospheric_entry
	show_sound = event_activating_unknown_technology
	event_chain = negative_mass

	is_triggered_only = yes

	immediate = {
		set_country_flag = b_world_spawned
		if = {
			limit = {
				OR  = {
					has_origin = origin_ocean_paradise
					has_origin = origin_ocean_machines
				}
			}
			home_planet = {
				solar_system = {
					spawn_planet = {
						class = pc_ocean
						location = root.home_planet
						orbit_angle_offset = 180
						size = 30
						init_effect = {
							set_name = {
								key = NAME_B_Planet
								variable_string = "[Root.GetHomeWorldName]"
							}
							clear_planet_modifiers = yes
							save_event_target_as = b_planet
							set_owner = root
							set_controller = root
							prevent_anomaly = yes
							clear_blockers = yes
							set_planet_entity = {
								entity = "ocean_paradise_planet_01_entity"
							}
							generate_start_deposits_and_blockers = yes
							remove_all_buildings = yes
							set_carrier_flag = colony_event
							colony = {
								generate_start_buildings_and_districts = yes
							}
						}
					}
					every_ambient_object = {
						limit = { has_ambient_object_flag = b_world_portal }
						destroy_ambient_object = this
					}
				}
			}
		}
		else_if = {
			limit = {
				has_origin = origin_life_seeded
			}
			home_planet = {
				solar_system = {
					spawn_planet = {
						class = pc_gaia
						location = root.home_planet
						orbit_distance_offset = 2
						orbit_angle_offset = 180
						size = 30
						init_effect = {
							set_name = {
								key = NAME_B_Planet
								variable_string = "[Root.GetHomeWorldName]"
							}
							clear_planet_modifiers = yes
							save_event_target_as = b_planet
							set_owner = root
							set_controller = root
							prevent_anomaly = yes
							clear_blockers = yes
							generate_start_deposits_and_blockers = yes
							remove_all_buildings = yes
							set_carrier_flag = colony_event
							colony = {
								generate_start_buildings_and_districts = yes
							}
						}
					}
					every_ambient_object = {
						limit = { has_ambient_object_flag = b_world_portal }
						destroy_ambient_object = this
					}
				}
			}
		}
		else_if = {
			limit = {
				is_apocalyptic_empire = yes
			}
			home_planet = {
				solar_system = {
					spawn_planet = {
						class = pc_nuked
						location = root.home_planet
						orbit_distance_offset = 2
						orbit_angle_offset = 180
						size = 20
						init_effect = {
							set_name = {
								key = NAME_B_Planet
								variable_string = "[Root.GetHomeWorldName]"
							}
							clear_planet_modifiers = yes
							save_event_target_as = b_planet
							set_owner = root
							set_controller = root
							prevent_anomaly = yes
							clear_blockers = yes
							generate_start_deposits_and_blockers = yes
							remove_all_buildings = yes
							set_carrier_flag = colony_event
							colony = {
								generate_start_buildings_and_districts = yes
							}
						}
					}
					every_ambient_object = {
						limit = { has_ambient_object_flag = b_world_portal }
						destroy_ambient_object = this
					}
				}
			}
		}
		else = {
			home_planet = {
				solar_system = {
					spawn_planet = {
						class = pc_ocean
						location = root.home_planet
						orbit_distance_offset = 2
						orbit_angle_offset = 180
						size = 18
						init_effect = {
							set_name = {
								key = NAME_B_Planet
								variable_string = "[Root.GetHomeWorldName]"
							}
							clear_planet_modifiers = yes
							save_event_target_as = b_planet
							set_owner = root
							set_controller = root
							prevent_anomaly = yes
							clear_deposits = yes
							remove_all_buildings = yes
							colony = {
								generate_start_buildings_and_districts = yes
							}
							set_carrier_flag = colony_event
							change_pc = root.owner_species
							if = {
								limit = {
									root.home_planet = {
										has_carrier_flag = planet_earth
									}
								}
								generate_earth_deposits_and_blockers = yes
								set_earth_entity = yes
							}
							else = {
								generate_start_deposits_and_blockers = yes
							}
						}
					}
					every_ambient_object = {
						limit = { has_ambient_object_flag = b_world_portal }
						destroy_ambient_object = this
					}
				}
			}
		}
		event_target:b_planet = {
			while = {
				count = 18
				create_pop_group = {
					species = root.species
					effect = { save_event_target_as = b_worlder_pop_group }
				}
				event_target:b_worlder_pop_group = { set_pop_group_flag = b_worlder }
			}
			every_owned_pop_group = {
				limit = {
					has_pop_group_flag = b_worlder
				}
				if = {
					limit = { is_robot_pop_group = yes }
					modify_species = {
						species = this
						add_trait = trait_robot_notofthisworld
					}
				}
				else = {
					modify_species = {
						species = this
						add_trait = trait_notofthisworld
					}
				}
			}
			add_modifier = {
				modifier = b_world_saved
				days = 3600
			}
		}
	}
	option = {
		name = colony.9850.a
		end_event_chain = negative_mass
		remove_modifier = "harvesting_negative_mass"
		random_situation = {
			limit = { is_situation_type = situation_negative_mass }
			destroy_situation = this
		}
	}
}

